pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Minimize post_residual to keep bins tight.
    // We normalize this by the bin capacity.
    score += (post_residual as f64 / bin_capacity as f64) * 10.0;

    // 2. Lookahead Synergy: If the next item fits perfectly into the current post_residual, 
    // we heavily reward this bin to create a "perfect pair".
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward exact matches or near-exact fits (within 5 units)
            let diff = (post_residual - next_item_size) as f64;
            score -= (100.0 - diff) * 0.5;
        } else {
            // Penalize creating a bin that cannot fit the next item if it's a large item
            if next_item_size > 50 {
                score += 20.0;
            }
        }
    }

    // 3. Fragmentation Control: Penalize bins that deviate significantly from the mean_residual.
    // This helps keep bins balanced in their remaining space.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.2;

    // 4. Strategic New Bin Opening:
    // If this is a new bin (bin_residual == bin_capacity), penalize it unless fitting_bins_count is low.
    if bin_residual == bin_capacity {
        // Only consider a new bin if we have very few options or the current open bins are poor fits.
        score += 40.0 - (open_bins_count as f64 * 0.5);
    } else {
        // If this is the last fitting bin, slightly incentivize using it to avoid opening a new one later.
        if fitting_bins_count == 1 {
            score -= 15.0;
        }
    }

    // 5. Progress weighting: In the final stages, be more conservative with new bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. If this is a new bin, apply a heavy penalty based on existing open bin density.
    // We only open a new bin if the existing fits are extremely poor.
    if bin_residual == bin_capacity {
        score += 45.0 + (mean_residual * 0.5);
    } else {
        // 2. Best-Fit logic: prioritize minimizing post_residual (already in score).

        // 3. Lookahead: reward bins that leave exactly enough space for the next item.
        if next_item_size > 0 {
            if post_residual == next_item_size {
                score -= 30.0;
            } else if post_residual > next_item_size {
                // Penalize wasted potential space that could have fit the next item.
                score += 5.0;
            }
        }

        // 4. Scarcity avoidance: if this is the only bin that can fit the item, 
        // prioritize it to keep it available for future items.
        if fitting_bins_count == 1 {
            score -= 15.0;
        }

        // 5. Global state normalization: penalize creating many open bins as the stream progresses.
        let progress = step_index as f64 / total_items as f64;
        score += (open_bins_count as f64) * progress * 2.0;
    }

    // 6. Avoid "dead zones": if post_residual is small but > 0, it's often unusable.
    // Penalize small gaps that are likely to remain empty.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    score
}

