        let density_factor = (open_bins_count as f64).powf(1.15) / (step_index as f64 + 1.0).sqrt();
        score += (750.0 * (1.1 - progress)) + (density_factor * 32.0);
    } else {
        // 4. Entropy Reduction: 
        // Penalize deviation from the mean_residual to cluster bins towards high utilization.
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.65;
    }

    // 5. Scarcity Constraint: 
    // Force utilization when choices are limited.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 1850.0 - (post_residual as f64 * 4.2);
    }

    // 6. Terminal Heuristic: 
    // Aggressive Best Fit exhaustion in final 15% to clear high-residual bins.
    let remaining = (total_items - step_index) as f64;
    if remaining < (total_items as f64 * 0.15) {
        score -= (bin_capacity - post_residual) as f64 * 4.5;
    }

    // 7. Global Density Bias: 
    // Penalize under-utilization using a non-linear decay function.
    if (bin_residual as f64) < (mean_residual * 0.75) && bin_residual != bin_capacity {
