pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the remaining space (Best Fit principle).
    let mut score = post;

    // Penalty for creating "dead space" that is too small for most items.
    // As we progress through the stream, we become more aggressive in avoiding small residuals.
    let dead_space_penalty = if post > 0.0 && post < 15.0 {
        (15.0 - post) * (1.0 + progress * 2.0)
    } else {
        0.0
    };
    score += dead_space_penalty;

    // Lookahead logic: if the next item is large, favor bins that leave enough space for it.
    if next_item_size > 0 {
        if post < next_item_size as f64 {
            score += (next_item_size as f64 - post) * 1.5;
        }
    }

    // Heuristic for opening new bins:
    // If this is an empty bin (bin_residual == bin_capacity), calculate the cost of opening it.
    if bin_residual == bin_capacity {
        // Opening a new bin is expensive. The cost decreases as the stream progresses
        // to ensure we don't end up with too many fragmented bins at the end.
        let open_cost = 45.0 - (progress * 15.0);

        // If we have many fitting bins, don't open a new one.
        let availability_bonus = (fitting_bins_count as f64) * 10.0;
        score = open_cost + availability_bonus;
    } else {
        // If we are placing in an existing bin, incentivize filling bins that are already 
        // near the mean residual to keep packing density uniform.
        let deviation_from_mean = (bin_residual as f64 - mean_residual).abs();
        score += deviation_from_mean * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the remaining space (Best Fit principle).
    let mut score = post;

    // Penalty for creating a 'fragmented' bin (small residual that is hard to fill later).
    // We penalize post_residual values in the 1-15 range heavily, 
    // especially as the stream progresses and the opportunity to fill small gaps decreases.
    if post > 0.0 && post < 20.0 {
        score += (20.0 - post) * (1.0 + progress * 2.0);
    }

    // Lookahead: If next_item_size is large, favor bins that can accommodate it.
    // If post_residual is smaller than next_item_size, we penalize the current choice 
    // to keep the larger space open for the upcoming item.
    if next_item_size > 0 {
        if post < next_item_size as f64 {
            score += (next_item_size as f64 - post) * 1.5;
        }
    }

    // Global state optimization: 
    // If many bins are open, we want to consolidate by filling the one with the smallest residual.
    // We add a scaling factor based on the difference between this bin's residual and the mean.
    let residual_diff = (bin_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1 * (1.0 - progress);

    // If this is the only bin that can fit the item, prioritize it strongly
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // Penalty for opening a new bin:
    // Only open if the existing fits are extremely poor (high post_residual).
    if bin_residual == bin_capacity {
        score += 35.0 + (progress * 15.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;
    let bin_res = bin_residual as f64;
    let cap = bin_capacity as f64;

    // Base score is the post_residual (Best Fit logic).
    // Penalize small residuals (fragments) that are difficult to fill later.
    // Penalty is non-linear: smaller post_residuals (1-15) are penalized heavily.
    let fragmentation_penalty = if post_res < 20.0 {
        (20.0 - post_res).powi(2) * 2.5
    } else {
        0.0
    };

    // Lookahead interaction: if next_item_size fits in current post_residual, reward this bin.
    let lookahead_bonus = if next_item_size > 0 && (post_res >= next_item_size as f64) {
        -15.0 * (1.0 - progress)
    } else {
        0.0
    };

    // Global state awareness: If we have many open bins, penalize opening a new one 
    // or using a bin that keeps the mean_residual high (wasted space).
    let efficiency_pressure = (mean_residual - post_res).abs() * progress;

    // New bin candidate logic:
    // If bin_residual == cap, we are evaluating opening a new bin.
    // We only want to open a new bin if the progress is early or the existing bins are too full to be useful.
    let new_bin_score = if bin_residual == bin_capacity {
        let base_new_bin = 45.0; // Threshold cost to open a new bin
        base_new_bin + (progress * 20.0) 
    } else {
        0.0
    };

    // Combined score: Lower is better.
    post_res + fragmentation_penalty + lookahead_bonus + efficiency_pressure + new_bin_score
}
